-- Gathering spots for While you're here (behavior.whileHereGather, off by default; Core/Engine.lua, Own.hereGather*):
-- where each herb, ore vein and fishing pool can spawn (Core/GatherData.lua, generated by `node tools/polestar.js
-- profession gathering spots`), for the kinds the character gathers now: its Herbalism, Mining or Fishing at the
-- node's skill. A spot is where a node CAN spawn, never a promise that one is up there. What the client tells an
-- addon about nodes that are up: the player's own tracking (Find Herbs, Find Minerals on the minimap:
-- Gather.Tracking) and the one object the Interact Key would pick (PLAYER_SOFT_INTERACT_CHANGED: Gather.UpNow).
-- Polestar changes neither the tracking nor the Interact Key's settings.
--
-- The spots of a continent are decoded the first time the option asks for them there, only the kinds the
-- character can gather, into cells of CELL yards; a skill that opens or closes a kind starts that again
-- (GATHER_CHANGED). Nothing of it is decoded while the option is off.
--
--   Gather.Register(data)              the generated data (Core/GatherData.lua)
--   Gather.Kind(k) -> { name, line, skill, ids } | nil
--   Gather.KindOf(objectId) -> k | nil
--   Gather.Can(k) -> true when the character gathers kind k now
--   Gather.KindsOn(c, out) -> out: the kinds with spots on continent c the character gathers (out reused, filled)
--   Gather.Nearest(c, wx, wy, radius, ok) -> k, yards, map, x, y, f, sx, sy, i | nil: the nearest spot within radius
--     yards of world point wx, wy on continent c that ok(k, i) accepts (i: the spot's number on c, the same until
--     GATHER_CHANGED); allocation-free once c is decoded
--   Gather.Tracking(line) -> true while the minimap tracks that profession's nodes
--   Gather.UpNow() -> objectId, k | nil: the node the Interact Key picks now
--   GATHER_UP_CHANGED: the Interact Key picked another object, or the minimap's tracking changed

local _, ns = ...
local Compat = ns.Compat
local floor, ceil, pairs, ipairs, type, tonumber = math.floor, math.ceil, pairs, ipairs, type, tonumber

local Gather = {}
ns.Gather = Gather

local CELL = 200 -- yards: a cell of a continent's index
local ROW = 4096 -- cells' key: x cell * ROW + y cell
local LINES = { 182, 186, 356 } -- Herbalism, Mining, Fishing
local FINDERS = { [182] = 2383, [186] = 2580 } -- Find Herbs, Find Minerals

local data -- the generated data: { kinds = { { name, line, skill, id... } }, maps = { [uiMapID] = "f;k:spots;..." } }
local kinds, byObject = {}, {}
local indexes = {} -- continent -> { cells, k, wx, wy, map, x, y, f, kinds = { [k] = true } } | false (no spots)

function Gather.Register(d)
	if type(d) ~= "table" then return end
	data, kinds, byObject, indexes = d, {}, {}, {}
	for k, row in ipairs(d.kinds or {}) do
		local ids = {}
		for i = 4, #row do
			ids[#ids + 1] = row[i]
			byObject[row[i]] = k
		end
		kinds[k] = { name = row[1], line = row[2], skill = row[3], ids = ids }
	end
end

function Gather.Kind(k) return kinds[k] end
function Gather.KindOf(id) return byObject[id] end

---------------------------------------------------------------------------
-- What the character gathers
---------------------------------------------------------------------------

local ranks -- line -> rank (nil: not learned), worked out again on skill changes

local function rankOf(line)
	if not ranks then
		ranks = {}
		local get = Compat.GetSkillRank
		for _, l in ipairs(LINES) do ranks[l] = get and get(l) or nil end
	end
	return ranks[line]
end

function Gather.Can(k)
	local kind = kinds[k]
	local rank = kind and rankOf(kind.line)
	return rank ~= nil and rank >= kind.skill
end

-- The kinds the character gathers, as one string: a skill-up that opens no kind changes nothing.
local function canKey()
	local parts = {}
	for k in ipairs(kinds) do
		if Gather.Can(k) then parts[#parts + 1] = k end
	end
	return table.concat(parts, ",")
end

local known = nil
ns.RegisterEvent("SKILL_LINES_CHANGED", function()
	ranks = nil
	local key = canKey()
	if known ~= nil and key ~= known then
		indexes = {}
		ns.Fire("GATHER_CHANGED")
	end
	known = key
end)

---------------------------------------------------------------------------
-- The spots
---------------------------------------------------------------------------

-- A spot's digits: base 60, no x or z (tools/lib/professions/gathering/spots.js).
local DIGIT = {}
do
	local digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWYabcdefghijklmnopqrstuvwy+/"
	for i = 1, #digits do DIGIT[digits:byte(i)] = i - 1 end
end
local STEPS = 3599 -- a coordinate in 3599ths of the map

-- A map percent from its two digits at position p of s.
local function percent(s, p)
	local a, b = DIGIT[s:byte(p)], DIGIT[s:byte(p + 1)]
	if not (a and b) then return nil end
	return (a * 60 + b) / STEPS * 100
end

-- Continent c's spots of the kinds the character gathers, decoded once (until GATHER_CHANGED). -> index | nil
local function index(c)
	local ix = indexes[c]
	if ix ~= nil then return ix or nil end
	if known == nil then known = canKey() end
	ix = { cells = {}, k = {}, wx = {}, wy = {}, map = {}, x = {}, y = {}, f = {}, kinds = {} }
	local n = 0
	for map, text in pairs(data and data.maps or {}) do
		local frame = text:sub(1, 1) == "e" and "e" or nil
		if Compat.MapToWorld(map, 50, 50, frame) == c then
			for k, spots in text:gmatch(";(%d+):([^;]*)") do
				k = tonumber(k)
				if k and Gather.Can(k) then
					for p = 1, #spots - 3, 4 do
						local x, y = percent(spots, p), percent(spots, p + 2)
						local sc, wx, wy
						if x and y then sc, wx, wy = Compat.MapToWorld(map, x, y, frame) end
						if sc == c then
							n = n + 1
							ix.k[n], ix.wx[n], ix.wy[n], ix.map[n], ix.x[n], ix.y[n], ix.f[n] = k, wx, wy, map, x, y, frame or false
							local key = floor(wx / CELL) * ROW + floor(wy / CELL)
							local cell = ix.cells[key]
							if not cell then
								cell = {}
								ix.cells[key] = cell
							end
							cell[#cell + 1] = n
							ix.kinds[k] = true
						end
					end
				end
			end
		end
	end
	indexes[c] = n > 0 and ix or false
	return n > 0 and ix or nil
end

function Gather.KindsOn(c, out)
	local n = 0
	local ix = c and index(c)
	if ix then
		for k in ipairs(kinds) do
			if ix.kinds[k] then
				n = n + 1
				out[n] = k
			end
		end
	end
	for i = n + 1, #out do out[i] = nil end
	return out
end

function Gather.Nearest(c, px, py, radius, ok)
	local ix = c and px and py and index(c)
	if not ix then return nil end
	local cells, K, WX, WY = ix.cells, ix.k, ix.wx, ix.wy
	local r2 = radius * radius
	local cx, cy, span = floor(px / CELL), floor(py / CELL), ceil(radius / CELL)
	local best, bestD
	for dx = -span, span do
		for dy = -span, span do
			local cell = cells[(cx + dx) * ROW + cy + dy]
			if cell then
				for j = 1, #cell do
					local i = cell[j]
					local ex, ey = WX[i] - px, WY[i] - py
					local d2 = ex * ex + ey * ey
					if d2 <= r2 and (not bestD or d2 < bestD) and (not ok or ok(K[i], i)) then best, bestD = i, d2 end
				end
			end
		end
	end
	if not best then return nil end
	return K[best], bestD ^ 0.5, ix.map[best], ix.x[best], ix.y[best], ix.f[best] or nil, WX[best], WY[best], best
end

---------------------------------------------------------------------------
-- What is up: the player's tracking, the Interact Key's pick
---------------------------------------------------------------------------

function Gather.Tracking(line)
	local spell, M = FINDERS[line], C_Minimap
	if not (spell and M and M.GetNumTrackingTypes and M.GetTrackingInfo) then return false end
	for i = 1, Compat.Readable(M.GetNumTrackingTypes()) or 0 do
		local info = M.GetTrackingInfo(i)
		if type(info) == "table" and Compat.Readable(info.active) == true and Compat.Readable(info.spellID) == spell then return true end
	end
	return false
end

local soft -- the game object the Interact Key picks now (its entry id), or nil

function Gather.UpNow()
	local k = soft and byObject[soft]
	if k then return soft, k end
	return nil
end

-- A game object's GUID: "GameObject-0-<server>-<instance>-<zone>-<entry>-<spawn>".
ns.RegisterEvent("PLAYER_SOFT_INTERACT_CHANGED", function(_, _, guid)
	guid = Compat.Readable(guid)
	local id = type(guid) == "string" and tonumber(guid:match("^GameObject%-[^-]*%-[^-]*%-[^-]*%-[^-]*%-(%d+)")) or nil
	if id == soft then return end
	local was = soft and byObject[soft]
	soft = id
	if was or (id and byObject[id]) then ns.Fire("GATHER_UP_CHANGED") end
end)

ns.RegisterEvent("MINIMAP_UPDATE_TRACKING", function() ns.Fire("GATHER_UP_CHANGED") end)
